-- 0046: Temporadas deportivas (Running, Raquetas y Cross Training). Idempotente: se puede correr más de una vez.
-- Requiere 0018 (tienda), 0024/0028/0037 (programas) y 0042 (suscripciones con billing).
--
-- Qué hace:
--   1. seasons: fechas oficiales, ventana de inscripción y precio de cada temporada (una por deporte y número).
--   2. Cada temporada es un programa (challenges_catalog.kind = 'programa') sembrado al final de este archivo.
--   3. program_start: en una temporada, el inicio es la fecha oficial (la semana sigue el calendario aunque se pause),
--      no se reinicia una temporada terminada y no se empieza después de su final. Los demás programas, igual que antes.
--   4. season_intake (cuestionario de inicio, filas propias), season_feedback (me gustó, muy difícil, saltado),
--      season_redemptions (la temporada incluida en el plan anual, una por periodo) y season_drafts (borradores del panel).
--   5. challenge_entitlements.source acepta 'anual' (canje del plan anual, monto 0).
--   6. admin_season_stats(): resumen anónimo para el panel (votos, saltos, retención y respuestas sin identificar a nadie).

-- ───────────── 1. Temporadas ─────────────
create table if not exists public.seasons (
  slug text primary key references public.challenges_catalog(slug) on update cascade on delete cascade,
  sport text not null check (sport in ('running', 'raquetas', 'cross')),
  number int not null check (number between 1 and 999),
  starts_on date not null,
  ends_on date not null,
  enroll_until date not null,
  price_minor int not null check (price_minor between 50 and 100000),
  created_at timestamptz not null default now(),
  unique (sport, number),
  check (ends_on = starts_on + 55 and extract(isodow from starts_on) = 1),
  check (enroll_until between starts_on - 365 and ends_on),
  check (slug = 'temporada-' || sport || '-' || number)
);
alter table public.seasons enable row level security;
drop policy if exists "temporadas: todos leen" on public.seasons;
create policy "temporadas: todos leen" on public.seasons for select using (true);
drop policy if exists "temporadas: editores" on public.seasons;
create policy "temporadas: editores" on public.seasons for all to authenticated using (public.is_content_editor()) with check (public.is_content_editor());
revoke insert, update, delete on public.seasons from anon;
grant select on public.seasons to anon, authenticated;

/** Temporada de un slug (null si el programa no es una temporada). */
create or replace function public._season_of(p_slug text)
returns public.seasons language sql stable security definer set search_path = public as $$
  select * from public.seasons where slug = p_slug;
$$;
revoke all on function public._season_of(text) from public, anon, authenticated;

-- ───────────── 5. Canje del plan anual ─────────────
do $$ begin
  alter table public.challenge_entitlements drop constraint if exists challenge_entitlements_source_check;
  alter table public.challenge_entitlements add constraint challenge_entitlements_source_check check (source in ('compra', 'cortesia', 'anual'));
end $$;

create table if not exists public.season_redemptions (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  slug text not null references public.seasons(slug) on update cascade,
  sub_id text not null check (char_length(sub_id) between 1 and 120),
  period_start date not null,
  created_at timestamptz not null default now(),
  -- Uno por periodo anual pagado (se renueva con el plan) y nunca la misma temporada dos veces.
  unique (sub_id, period_start),
  unique (user_id, slug)
);
alter table public.season_redemptions enable row level security;
drop policy if exists "canjes: propios o staff" on public.season_redemptions;
create policy "canjes: propios o staff" on public.season_redemptions for select using (user_id = (select auth.uid()) or public.is_staff());
revoke insert, update, delete on public.season_redemptions from anon, authenticated; -- solo el servidor (service_role)

-- ───────────── 4. Cuestionario de inicio ─────────────
create table if not exists public.season_intake (
  user_id uuid not null references auth.users(id) on delete cascade,
  slug text not null references public.seasons(slug) on update cascade on delete cascade,
  answers jsonb not null check (jsonb_typeof(answers) = 'object' and pg_column_size(answers) <= 6000),
  plan jsonb not null default '{}'::jsonb check (jsonb_typeof(plan) = 'object' and pg_column_size(plan) <= 4000),
  -- Desde qué semana rige la última versión (al editar, el plan cambia de esa semana en adelante).
  from_week int not null default 1 check (from_week between 1 and 9),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, slug)
);
alter table public.season_intake enable row level security;
drop policy if exists "cuestionario: propio o staff lee" on public.season_intake;
create policy "cuestionario: propio o staff lee" on public.season_intake for select using (user_id = (select auth.uid()) or public.is_staff());
drop policy if exists "cuestionario: propio con la temporada" on public.season_intake;
create policy "cuestionario: propio con la temporada" on public.season_intake for insert to authenticated with check (user_id = (select auth.uid()) and public.i_own_challenge(slug));
drop policy if exists "cuestionario: edita el propio" on public.season_intake;
create policy "cuestionario: edita el propio" on public.season_intake for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and public.i_own_challenge(slug));
revoke delete on public.season_intake from anon, authenticated;
revoke all on public.season_intake from anon;

-- ───────────── 4b. Lo que gustó ─────────────
create table if not exists public.season_feedback (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  slug text not null references public.seasons(slug) on update cascade on delete cascade,
  week int not null check (week between 1 and 8),
  day int not null check (day between 1 and 6),
  exercise_id text not null check (exercise_id ~ '^(ds:\d{4}|[a-z][a-zA-Z0-9_]{1,30})$'),
  liked boolean,
  difficulty text check (difficulty is null or difficulty in ('dificil', 'facil')),
  skipped boolean not null default false,
  completed boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, slug, week, day, exercise_id)
);
create index if not exists season_feedback_slug on public.season_feedback (slug, exercise_id);
alter table public.season_feedback enable row level security;
drop policy if exists "opiniones: propias o staff leen" on public.season_feedback;
create policy "opiniones: propias o staff leen" on public.season_feedback for select using (user_id = (select auth.uid()) or public.is_staff());
drop policy if exists "opiniones: propias con la temporada" on public.season_feedback;
create policy "opiniones: propias con la temporada" on public.season_feedback for insert to authenticated with check (user_id = (select auth.uid()) and public.i_own_challenge(slug));
drop policy if exists "opiniones: edita las propias" on public.season_feedback;
create policy "opiniones: edita las propias" on public.season_feedback for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and public.i_own_challenge(slug));
revoke delete on public.season_feedback from anon, authenticated;
revoke all on public.season_feedback from anon;

-- ───────────── 4c. Borradores de la próxima temporada (solo el panel) ─────────────
create table if not exists public.season_drafts (
  id bigint generated always as identity primary key,
  sport text not null check (sport in ('running', 'raquetas', 'cross')),
  number int not null check (number between 2 and 999),
  content jsonb not null check (jsonb_typeof(content) = 'object' and pg_column_size(content) <= 200000),
  notes text check (notes is null or char_length(notes) <= 4000),
  status text not null default 'borrador' check (status in ('borrador', 'publicado', 'descartado')),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  published_at timestamptz
);
alter table public.season_drafts enable row level security;
drop policy if exists "borradores: editores" on public.season_drafts;
create policy "borradores: editores" on public.season_drafts for all to authenticated using (public.is_content_editor()) with check (public.is_content_editor());
revoke all on public.season_drafts from anon;

-- ───────────── 3. Empezar una temporada ─────────────
create or replace function public.program_start(p_slug text, p_day date, p_pause_current boolean default false)
returns text language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); c record; cur public.user_programs%rowtype; other public.user_programs%rowtype; s public.seasons%rowtype;
begin
  if v_uid is null then raise exception 'No autorizado' using errcode = '42501'; end if;
  if p_day is null or not public._is_today_somewhere(p_day) then raise exception 'Fecha inválida' using errcode = '22023'; end if;
  select slug, kind, status, price_usd into c from public.challenges_catalog where slug = p_slug;
  if not found or c.kind <> 'programa' then raise exception 'Programa inválido' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('bb:programas:' || v_uid::text, 0));
  select * into cur from public.user_programs where user_id = v_uid and slug = p_slug;
  if c.status <> 'publicado' and cur.id is null and not (c.status = 'oculto' and public._owns_challenge(v_uid, p_slug)) then raise exception 'Este programa ya no está disponible' using errcode = '22023'; end if;
  if not public._has_app_access(v_uid) then raise exception 'Sin plan activo' using errcode = '42501'; end if;
  if c.price_usd > 0 and not public._owns_challenge(v_uid, p_slug) then raise exception 'Compra este programa para empezarlo' using errcode = '42501'; end if;
  if not exists (select 1 from public.program_sessions where slug = p_slug) then raise exception 'Este programa todavía no tiene sesiones' using errcode = 'P0001'; end if;
  select * into s from public.seasons where slug = p_slug;
  -- 0046: una temporada terminada no se empieza ni se repite.
  if s.slug is not null and p_day > s.ends_on then raise exception 'Esta temporada ya terminó' using errcode = 'P0001'; end if;
  if s.slug is not null and cur.status = 'completado' then raise exception 'Esta temporada no se repite' using errcode = 'P0001'; end if;
  if cur.id is not null and cur.status = 'activo' then return 'activo'; end if;
  for other in select * from public.user_programs where user_id = v_uid and status = 'activo' and slug <> p_slug loop
    if not coalesce(p_pause_current, false) then raise exception 'Ya tienes un programa activo' using errcode = 'P0001'; end if;
    update public.user_programs set status = 'pausado', paused_on = greatest(p_day, other.started_on), updated_at = now() where id = other.id;
  end loop;
  if s.slug is not null then
    -- La semana de una temporada sigue el calendario oficial: inicio = fecha oficial y sin días en pausa.
    if cur.id is null then
      insert into public.user_programs (user_id, slug, status, started_on) values (v_uid, p_slug, 'activo', s.starts_on);
      return 'empezado';
    end if;
    update public.user_programs set status = 'activo', started_on = s.starts_on, paused_on = null, paused_days = 0, completed_at = null, updated_at = now() where id = cur.id;
    return 'reanudado';
  end if;
  if cur.id is null then
    insert into public.user_programs (user_id, slug, status, started_on) values (v_uid, p_slug, 'activo', p_day);
    return 'empezado';
  elsif cur.status = 'pausado' then
    update public.user_programs set status = 'activo', paused_days = least(3650, paused_days + greatest(0, p_day - coalesce(paused_on, p_day))), paused_on = null, updated_at = now() where id = cur.id;
    return 'reanudado';
  end if;
  update public.user_programs set status = 'activo', started_on = p_day, paused_on = null, paused_days = 0, completed_at = null, updated_at = now() where id = cur.id;
  return 'reiniciado';
end $$;
revoke execute on function public.program_start(text, date, boolean) from public, anon;
grant execute on function public.program_start(text, date, boolean) to authenticated;

-- ───────────── 6. Resumen para el panel (anónimo) ─────────────
create or replace function public.admin_season_stats(p_slug text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v jsonb;
begin
  if not public.is_staff() then raise exception 'No autorizado' using errcode = '42501'; end if;
  select jsonb_build_object(
    'owners', (select count(*) from public.challenge_entitlements where challenge_slug = p_slug),
    'started', (select count(*) from public.user_programs where slug = p_slug),
    'feedback', coalesce((select jsonb_agg(jsonb_build_object('exercise_id', exercise_id, 'week', week, 'liked', liked, 'difficulty', difficulty, 'skipped', skipped, 'completed', completed))
       from public.season_feedback where slug = p_slug), '[]'::jsonb),
    -- Semanas con al menos una sesión hecha, por persona (sin decir quién).
    'weeks', coalesce((select jsonb_agg(ws) from (
       select jsonb_agg(distinct (regexp_match(w.template, ':(\d{1,2})\.\d$'))[1]::int) as ws
         from public.workouts w where w.template like 'p:' || p_slug || ':%' group by w.user_id) x), '[]'::jsonb),
    'intakes', coalesce((select jsonb_agg(answers) from public.season_intake where slug = p_slug), '[]'::jsonb)
  ) into v;
  return v;
end $$;
revoke execute on function public.admin_season_stats(text) from public, anon;
grant execute on function public.admin_season_stats(text) to authenticated;

-- ───────────── 2. Siembra de la Temporada 1 (generada con scripts/gen-temporadas-seed.ts) ─────────────
insert into public.challenges_catalog (slug, title, description, days, rules, status, price_usd, difficulty, minutes, cover, icon, verify, grace, xp, badge, reward_title, start_mode, featured, coming_soon, safety_note, sort, kind, program) values
  ('temporada-running-1', 'Temporada 1: Running', 'Corre más fuerte, más rápido y con menos lesiones. 8 semanas con fechas oficiales, acomodadas a tus días de carrera.', 56, '{}'::jsonb, 'publicado', 14.99, 'media', 45, 'ember', 'run', 'workout', 0, 400, 'Running T1', 'Zancada de acero', 'libre', false, false, 'Si tienes dolor, una lesión reciente o una condición médica, consulta con un profesional antes de empezar. El cuestionario solo cambia ejercicios: no es un diagnóstico.', 1, 'programa', $j${"phases":[{"name":"Base","weeks":3,"focus":"Técnica, fuerza general y tendones fuertes. Cargas cómodas, 2 o 3 repeticiones en reserva."},{"name":"Descarga","weeks":1,"deload":true,"focus":"Semana ligera: menos series y carga. Llegas con energía a la fase de potencia."},{"name":"Potencia","weeks":3,"focus":"Más carga en los básicos y saltos más explosivos. Lo que ganaste en la base se vuelve velocidad."},{"name":"Afinar y prueba","weeks":1,"deload":true,"focus":"Volumen bajo y tu prueba final: compara con la semana 1."}],"daysPerWeek":4,"sessionMinutes":45,"level":"todos","equipment":"Gimnasio, con versión para casa","adapt":true,"who":"Para quien corre de 5K a maratón o trail y quiere correr más fuerte y con menos lesiones, con fuerza acomodada alrededor de sus días de carrera.","result":"Fuerza pesada, pliometría y prevención de lesiones 2 a 4 veces por semana, sin tocar tus días de correr.","outcomes":["Fuerza de piernas y glúteo para una zancada más eficiente","Pantorrilla, sóleo y tibia fuertes","Saltos cortos para una zancada elástica","Prueba final para comparar con la semana 1"],"keyLifts":["squat","rdl"],"nutrition":{"mode":"recomp","proteinPerKg":1.6,"note":"Come para rendir: carbohidratos antes de tu deporte y proteína en cada comida."},"previewExercise":"rdl","experience":{"mode":"Modo Running","welcome":"Te damos la bienvenida a tu Temporada de Running. Tu fuerza va lejos de tu carrera larga: corres igual que siempre y llegas más fuerte cada semana.","habits":[{"key":"entreno","label":"Tu sesión de fuerza o tu carrera","kind":"entreno"},{"key":"carbo","label":"Carbohidratos antes de correr","kind":"check"},{"key":"agua","label":"Toma 8 vasos de agua","kind":"agua","target":8},{"key":"sueno","label":"Duerme 7 horas","kind":"sueno","target":7}],"tips":["Semana 1: cargas cómodas. Termina cada serie sintiendo que podías hacer 2 o 3 más; tus tendones se adaptan más lento que tus músculos.","Semana 2: nunca piernas pesadas el día antes de tu carrera larga. Si la mueves, mueve también tu fuerza.","Semana 3: el sóleo (pantorrilla con rodilla doblada) carga más que cualquier otro músculo al correr. No te saltes ese ejercicio.","Semana 4: semana ligera. Menos series para llegar con energía a la fase de potencia.","Semana 5: empieza la potencia. En los saltos, cada repetición es rápida y limpia; si se vuelven lentos, para.","Semana 6: si un día tus piernas no responden, haz la sesión con menos carga. Correr bien manda.","Semana 7: última semana fuerte. Mira cuánto subieron tus pesos desde la semana 1.","Semana 8: afina y prueba. Volumen bajo y tu prueba final para comparar."],"coachFocus":"Fuerza para corredores: cadena posterior, una pierna, pantorrilla y sóleo, pliometría y prevención de lesiones, siempre acomodada a sus días de carrera. Habla de su carrera larga y de su próximo evento.","restDay":"Corre según tu plan o camina 20 minutos y estira pantorrillas y cadera","food":["Antes de una carrera larga: carbohidratos de fácil digestión 2 a 3 horas antes.","Después de correr o entrenar: proteína y carbohidratos en la siguiente comida.","Más de 75 minutos corriendo: lleva algo para tomar o comer en el camino.","Proteína en cada comida para recuperar."]}}$j$::jsonb)
on conflict (slug) do nothing;
insert into public.challenges_catalog (slug, title, description, days, rules, status, price_usd, difficulty, minutes, cover, icon, verify, grace, xp, badge, reward_title, start_mode, featured, coming_soon, safety_note, sort, kind, program) values
  ('temporada-raquetas-1', 'Temporada 1: Raquetas', 'Tenis y pádel: más potencia, mejores desplazamientos y brazo sano. 8 semanas con fechas oficiales, acomodadas a tus días de partido.', 56, '{}'::jsonb, 'publicado', 16.99, 'media', 45, 'selva', 'target', 'workout', 0, 400, 'Raquetas T1', 'Brazo de hierro', 'libre', false, false, 'Si tienes dolor, una lesión reciente o una condición médica, consulta con un profesional antes de empezar. El cuestionario solo cambia ejercicios: no es un diagnóstico.', 2, 'programa', $j${"phases":[{"name":"Base","weeks":3,"focus":"Técnica, fuerza general y tendones fuertes. Cargas cómodas, 2 o 3 repeticiones en reserva."},{"name":"Descarga","weeks":1,"deload":true,"focus":"Semana ligera: menos series y carga. Llegas con energía a la fase de potencia."},{"name":"Potencia","weeks":3,"focus":"Más carga en los básicos y saltos más explosivos. Lo que ganaste en la base se vuelve velocidad."},{"name":"Afinar y prueba","weeks":1,"deload":true,"focus":"Volumen bajo y tu prueba final: compara con la semana 1."}],"daysPerWeek":4,"sessionMinutes":45,"level":"todos","equipment":"Gimnasio, con versión para casa","adapt":true,"who":"Para quien juega tenis o pádel y quiere más potencia, mejores desplazamientos y cuidar codo y hombro, sin llegar sin energía al partido.","result":"Fuerza de piernas, potencia de rotación, agilidad y salud de hombro y antebrazo, acomodadas a tus partidos.","outcomes":["Piernas que frenan y cambian de dirección","Rotación potente desde la cadera","Hombro, codo y muñeca más fuertes","Prueba final para comparar con la semana 1"],"keyLifts":["squat","ds:0431"],"nutrition":{"mode":"recomp","proteinPerKg":1.6,"note":"Come para rendir: carbohidratos antes de tu deporte y proteína en cada comida."},"previewExercise":"goblet","experience":{"mode":"Modo Raquetas","welcome":"Te damos la bienvenida a tu Temporada de Raquetas. Más potencia, mejores desplazamientos y brazo sano, con energía para tus partidos.","habits":[{"key":"entreno","label":"Tu sesión o tu partido","kind":"entreno"},{"key":"brazo","label":"5 minutos de hombro y muñeca","kind":"check"},{"key":"agua","label":"Toma 8 vasos de agua","kind":"agua","target":8},{"key":"sueno","label":"Duerme 7 horas","kind":"sueno","target":7}],"tips":["Semana 1: el golpe nace en las piernas. Fuerza de piernas primero, brazo después.","Semana 2: nunca piernas pesadas el día antes de un partido. Si cambia tu partido, cambia tu sesión.","Semana 3: el manguito rotador se entrena con poco peso y mucho control. Lento y sin dolor.","Semana 4: semana ligera. Juega más suelto y deja que el cuerpo absorba lo que entrenaste.","Semana 5: potencia de rotación: gira desde la cadera, no desde el brazo.","Semana 6: en los saltos laterales, frena firme como cuando llegas a una bola abierta.","Semana 7: última semana fuerte. Compara tus saltos laterales con la semana 1.","Semana 8: afina y prueba. Llega con energía a tus partidos."],"coachFocus":"Tenis y pádel: fuerza de piernas, potencia de rotación, agilidad lateral y salud de hombro, codo y muñeca, acomodado a sus partidos. Habla de sus partidos y torneos.","restDay":"Juega según tu plan o camina 20 minutos y haz movilidad de hombro","food":["Antes de jugar: una comida con carbohidratos 2 a 3 horas antes.","Partidos de más de 90 minutos: agua y algo de carbohidrato en los cambios de lado.","Después del partido: proteína y carbohidratos para recuperar.","Si sudas mucho, suma sal a tu comida del día."]}}$j$::jsonb)
on conflict (slug) do nothing;
insert into public.challenges_catalog (slug, title, description, days, rules, status, price_usd, difficulty, minutes, cover, icon, verify, grace, xp, badge, reward_title, start_mode, featured, coming_soon, safety_note, sort, kind, program) values
  ('temporada-cross-1', 'Temporada 1: Cross Training', 'Fuerza, técnica y acondicionamiento, con escalas para cada nivel. 8 semanas con fechas oficiales, acomodadas a tus días de box.', 56, '{}'::jsonb, 'publicado', 18.99, 'media', 45, 'noche', 'bolt', 'workout', 0, 400, 'Cross Training T1', 'Motor completo', 'libre', false, false, 'Si tienes dolor, una lesión reciente o una condición médica, consulta con un profesional antes de empezar. El cuestionario solo cambia ejercicios: no es un diagnóstico.', 3, 'programa', $j${"phases":[{"name":"Base","weeks":3,"focus":"Técnica, fuerza general y tendones fuertes. Cargas cómodas, 2 o 3 repeticiones en reserva."},{"name":"Descarga","weeks":1,"deload":true,"focus":"Semana ligera: menos series y carga. Llegas con energía a la fase de potencia."},{"name":"Potencia","weeks":3,"focus":"Más carga en los básicos y saltos más explosivos. Lo que ganaste en la base se vuelve velocidad."},{"name":"Afinar y prueba","weeks":1,"deload":true,"focus":"Volumen bajo y tu prueba final: compara con la semana 1."}],"daysPerWeek":4,"sessionMinutes":45,"level":"todos","equipment":"Gimnasio, con versión para casa","adapt":true,"who":"Para quien va a un box o entrena funcional y quiere más fuerza, mejor técnica y más aguante, con escalas para cada movimiento.","result":"Bloques de fuerza, técnica de olímpicos con carga ligera, acondicionamiento con escalas y gimnásticos.","outcomes":["Sentadilla, peso muerto y press más fuertes","Técnica de cargada y swing","Más rondas en el mismo tiempo","Benchmark en las semanas 1 y 8"],"keyLifts":["squat","deadlift"],"nutrition":{"mode":"recomp","proteinPerKg":1.6,"note":"Come para rendir: carbohidratos antes de tu deporte y proteína en cada comida."},"previewExercise":"goblet","experience":{"mode":"Modo Cross Training","welcome":"Te damos la bienvenida a tu Temporada de Cross Training. Fuerza, técnica y acondicionamiento con escalas: primero el movimiento, después la carga.","habits":[{"key":"entreno","label":"Tu sesión o tu clase","kind":"entreno"},{"key":"proteina","label":"Proteína en cada comida","kind":"proteina"},{"key":"agua","label":"Toma 8 vasos de agua","kind":"agua","target":8},{"key":"sueno","label":"Duerme 7 horas","kind":"sueno","target":7}],"tips":["Semana 1: anota tu benchmark. Es tu punto de partida, no un examen.","Semana 2: técnica antes que carga en la cargada y el swing. Si la forma se rompe, baja el peso.","Semana 3: elige la escala que te deja moverte bien todo el circuito. Eso es lo que más te hace avanzar.","Semana 4: semana ligera. Menos series y más movilidad.","Semana 5: empieza la potencia: series cortas y pesadas con descanso completo.","Semana 6: los gimnásticos se ganan con progresiones. Nada de forzar el rango con dolor.","Semana 7: última semana fuerte. Mira tus pesos de la semana 1.","Semana 8: repite tu benchmark y compara."],"coachFocus":"Cross Training: fuerza, técnica de olímpicos con carga ligera, acondicionamiento con escalas y progresiones gimnásticas, sin forzar con dolor. Respeta lo que la persona no puede o no quiere hacer.","restDay":"Descanso activo: 20 minutos de caminata y movilidad de cadera y hombro","food":["Proteína en cada comida para recuperar entre sesiones.","Carbohidratos alrededor de tus sesiones fuertes.","Agua durante el día, no solo en el entreno.","Si entrenas en ayunas y te mareas, come algo ligero antes."]}}$j$::jsonb)
on conflict (slug) do nothing;
